def unit_questions(grade, unit):
    literary = unit['practice']
    if grade == 11:
        orthodox = SENIOR_QUESTIONS[unit['id']]
    else:
        orthodox = literary + ' ' + SOURCE_QUESTIONS[unit['quote']][0 if grade <= 4 else 1]
    return lens_questions(literary, orthodox)


